  gauge(mktV, engV) {
    const cx = 170, cy = 178, r = 138;
    const pt = (v) => { const th = Math.PI * (1 - v / 100); return { x: +(cx + r * Math.cos(th)).toFixed(1), y: +(cy - r * Math.sin(th)).toFixed(1) }; };
    const m = mktV == null ? 52 : mktV, e = engV == null ? 60 : engV;
    const p0 = pt(0), p100 = pt(100), pm = pt(m), pe = pt(e);
    return { cx, cy, full: `M ${p0.x} ${p0.y} A ${r} ${r} 0 0 1 ${p100.x} ${p100.y}`, edge: `M ${pm.x} ${pm.y} A ${r} ${r} 0 0 1 ${pe.x} ${pe.y}`, eng: pe, mkt: pm };
  }

  clvChart() {
    const R = window.REAL || {};
    const collecting = !R.clv || !R.clv.spark || R.clv.n === 0 || R.clvCollecting === true;
    const data = collecting
      ? [0, 0.001, -0.001, 0.001, -0.001, 0.001, -0.001, 0.001, -0.001, 0.001, -0.001, 0.001, -0.001, 0.001, -0.001, 0.001, -0.001, 0.0]
      : R.clv.spark;
    const W = 520, H = 200, yMin = -0.1, yMax = 0.4;
    const X = i => +(i / (data.length - 1) * W).toFixed(1);
    const Y = v => +(H - (v - yMin) / (yMax - yMin) * H).toFixed(1);
    const line = data.map((v, i) => `${i ? 'L' : 'M'} ${X(i)} ${Y(v)}`).join(' ');
    const area = `M ${X(0)} ${Y(data[0])} ` + data.map((v, i) => `L ${X(i)} ${Y(v)}`).join(' ') + ` L ${W} ${Y(yMin)} L 0 ${Y(yMin)} Z`;
    return { line, area, baseY: Y(0), dotX: X(data.length - 1), dotY: Y(data[data.length - 1]), collecting };
  }

  cal() {
    // Real 4-band calibration from CALIB (engine output).
    // Bands: 60-70% actual 63%, 70-80% actual 73%, 80-85% actual 80%, 85%+ actual 85%
    const R = window.REAL || {};
    const bands = R.calib || [];
    if (!bands.length) {
      return { noData: true, bands: [], diag: 'M 0 220 L 300 0' };
    }
    // Map bands to bar widths: actual/100 * maxWidth
    const maxW = 280;
    const calibBars = bands.map((b, i) => ({
      band: b.band,
      actual: b.actual,
      n: b.n,
      barW: Math.round(b.actual / 100 * maxW),
      color: b.actual >= 80 ? '#35e39a' : (b.actual >= 70 ? '#f5b23d' : '#8791ab'),
      nFormatted: b.n >= 1000 ? (b.n / 1000).toFixed(1) + 'k' : String(b.n),
    }));
    return { noData: false, bands: calibBars, diag: 'M 0 220 L 300 0' };
  }

